602	    pub fn relayout(&mut self) {
603	        // Capacity depends on the other members and viewport, not just the
604	        // rejected client's hints. Retry retained buffers on model changes so
605	        // a static client does not need to commit again after capacity returns.
606	        // One arena-order pass (at most the 1,024 owned roles), no timer or
607	        // recursive relayout. Recovery preserves the current selection.
608	        let pending: Vec<_> = self
609	            .windows
610	            .iter()
611	            .filter_map(|(id, item)| {
612	                (item.buffered
613	                    && !item.mapped
614	                    && item.admission_error.is_some()
615	                    && item.window.alive())
616	                .then_some(id)
617	            })
618	            .collect();
619	        let mut admitted = false;
620	        for id in pending {
621	            let surface = self
622	                .windows
623	                .get(id)
624	                .and_then(|item| item.window.toplevel())
625	                .expect("live rejected role in one dispatch")
626	                .wl_surface()
627	                .clone();
628	            if self
629	                .layout
630	                .insert_with_focus(id, self.constraints_for(&surface), false)
631	                .is_ok()
632	            {
633	                if self.apply_initial_maximize(id).is_err() {
634	                    let _ = self.layout.remove(id);
635	                    continue;
636	                }
637	                let item = self.windows.get_mut(id).expect("live dispatch ID");
638	                item.mapped = true;
639	                item.admission_error = None;
640	                self.stats.maps += 1;
641	                self.bump_sequence();
642	                admitted = true;
643	                tracing::info!(%id, "window_admission_recovered");
644	            }
645	        }
646	        for placement in self.layout.placements() {
647	            let Some(item) = self.windows.get(placement.window) else {
648	                continue;
649	            };
650	            if !item.mapped {
651	                continue;
652	            }
653	            if let Some(toplevel) = item.window.toplevel() {
654	                toplevel.with_pending_state(|s| {
655	                    s.size = Some((placement.rect.width.round() as i32, placement.rect.height.round() as i32).into());
656	                    if self.layout.is_maximized(placement.window) {
657	                        s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
658	                    } else {
659	                        s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
660	                    }
661	                    if self.layout.is_minimized(placement.window) {
662	                        s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
663	                    } else {
664	                        s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
665	                    }
666	                    if placement.focused { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
667	                    else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
668	                });
669	                crate::configure::send_pending(toplevel);
670	            }
671	            if placement.visible {
672	                let rect = self.layout.camera().rect_to_view(placement.rect);
673	                self.space.map_element(
674	                    item.window.clone(),
675	                    (rect.x.round() as i32, rect.y.round() as i32),
676	                    placement.focused,
677	                );
678	            } else {
679	                if let Some(toplevel) = item.window.toplevel() {
